import type { HevcWasmBackend, RgbaFrame } from './backend.js';

/** Minimal shape of the Emscripten module generated by `native/build.sh`. */
interface De265Module {
  _hevc_init(threads: number): number;
  _hevc_push(ptr: number, len: number, pts: number): number;
  _hevc_pull(): number;
  _hevc_pts(): number;
  _hevc_out_ptr(): number;
  _hevc_width(): number;
  _hevc_height(): number;
  _hevc_reset(): void;
  _hevc_free(): void;
  _malloc(size: number): number;
  _free(ptr: number): void;
  HEAPU8: Uint8Array;
}

type De265Factory = (opts?: Record<string, unknown>) => Promise<De265Module>;

export interface Libde265Options {
  /**
   * URL/specifier of the Emscripten glue (`hevc.js`). Defaults to the binary
   * bundled in this package. In a bundler (e.g. Next.js) serve `hevc.js` +
   * `hevc.wasm` as static assets and pass their URL here, e.g. `/hevc/hevc.js`.
   */
  glueUrl?: string;
  /** Resolve the location of `hevc.wasm` if not co-located with `hevc.js`. */
  locateFile?: (path: string) => string;
  /**
   * Number of decode worker threads. Defaults to `hardwareConcurrency` capped at
   * the wasm thread pool size (8). Requires a cross-origin-isolated page
   * (COOP/COEP) for SharedArrayBuffer; otherwise the module fails to load.
   */
  threads?: number;
}

const MAX_THREADS = 8;

function resolveThreads(requested?: number): number {
  if (requested && requested > 0) return Math.min(requested, MAX_THREADS);
  const hc = (globalThis as { navigator?: { hardwareConcurrency?: number } }).navigator?.hardwareConcurrency;
  return Math.min(hc && hc > 0 ? hc : 4, MAX_THREADS);
}

/**
 * The real libde265 WASM backend. Loads the Emscripten glue produced by
 * `native/build.sh` (wasm/hevc.js + hevc.wasm) and adapts it to
 * {@link HevcWasmBackend}.
 *
 * The glue is imported dynamically (via a non-literal specifier) so the package
 * typechecks and builds even before the binary has been compiled.
 */
export function createLibde265Backend(options: Libde265Options = {}): HevcWasmBackend {
  let mod: De265Module | null = null;

  return {
    async init(): Promise<void> {
      const spec = options.glueUrl ?? '../wasm/hevc.js';
      const imported = (await import(/* @vite-ignore */ /* webpackIgnore: true */ spec)) as { default: De265Factory };
      mod = await imported.default(options.locateFile ? { locateFile: options.locateFile } : {});
      const rc = mod._hevc_init(resolveThreads(options.threads));
      if (rc !== 0) throw new Error(`libde265: init failed (code ${rc})`);
    },

    decode(accessUnit: Uint8Array, pts: number): RgbaFrame | null {
      if (!mod) throw new Error('libde265: backend not initialized');

      const len = accessUnit.length;
      const ptr = mod._malloc(len);
      if (!ptr) return null;
      mod.HEAPU8.set(accessUnit, ptr);
      mod._hevc_push(ptr, len, pts);
      mod._free(ptr);

      if (mod._hevc_pull() !== 1) return null;

      const width = mod._hevc_width();
      const height = mod._hevc_height();
      const out = mod._hevc_out_ptr();

      // Packed RGBA, copied out of the wasm heap.
      const data = mod.HEAPU8.slice(out, out + width * height * 4);
      return { width, height, pts: mod._hevc_pts(), data };
    },

    reset(): void {
      mod?._hevc_reset();
    },

    destroy(): void {
      mod?._hevc_free();
      mod = null;
    },
  };
}
